import java.io.*;
import java.util.*;

public class Main {
    static int[] altura;
    static ArrayList<Integer>[] adj;
    static int[] memo;

    static int dfs(int v) {
        if (memo[v] != -1) return memo[v];

        int melhor = 0;
        for (int u : adj[v]) {
            if (altura[u] < altura[v]) {
                melhor = Math.max(melhor, 1 + dfs(u));
            }
        }
        return memo[v] = melhor;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int s = fs.nextInt();
        int t = fs.nextInt();
        int p = fs.nextInt() - 1;

        altura = new int[s];
        for (int i = 0; i < s; i++) altura[i] = fs.nextInt();

        adj = new ArrayList[s];
        for (int i = 0; i < s; i++) adj[i] = new ArrayList<>();

        for (int i = 0; i < t; i++) {
            int a = fs.nextInt() - 1;
            int b = fs.nextInt() - 1;
            adj[a].add(b);
            adj[b].add(a);
        }

        memo = new int[s];
        Arrays.fill(memo, -1);

        System.out.println(dfs(p));
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream in) {
            this.in = in;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int value = 0;
            while (c > ' ') {
                value = value * 10 + c - '0';
                c = read();
            }
            return value * sign;
        }
    }
}
